def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []
    if not b:
        return sorted(a)

    # Merge overlapping intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    next_ranges.append([c_start, c_end])
                else:
                    # Overlap exists
                    if c_start < b_start:
                        next_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        next_ranges.append([b_end, c_end])
            current_ranges = next_ranges

        result.extend(current_ranges)

    # Merge touching intervals
    if not result:
        return []

    result_sorted = sorted(result)
    merged_result = []
